'use strict';
const $=id=>document.getElementById(id), clone=o=>JSON.parse(JSON.stringify(o));
const zones=['Основной фон','Акцентная секция','Вставки','Цоколь и тёмные стены'];
const originalHex=['#e7e5df','#7891a6','#9c998f','#404549'];
const state={view:0,zone:1,colors:[null,null,null,null],compare:false,split:50,ready:false,mask:false};
const data=[],ctx=$('canvas').getContext('2d',{willReadFrequently:true});let saved=[],toastTimer,frame,painting=false,lastPoint=null,currentStroke=null;
const paletteByCode=Object.fromEntries(RAL.map(c=>[c.code,c]));
function rgb(hex){return [1,3,5].map(i=>parseInt(hex.slice(i,i+2),16));}
function colorRGB(c){if(!c)return null;return rgb(paletteByCode[c.code].hex).map(v=>Math.round(v+(255-v)*(c.light/100)));}
function cssColor(c,i){return c?'rgb('+colorRGB(c).join(',')+')':originalHex[i];}
function label(c){return c?'RAL '+c.code+(c.light?' + '+c.light+'%':''):'Исходный цвет';}
function toast(t){$('toast').textContent=t;$('toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('visible'),3000);}
function persist(){try{localStorage.setItem('facade-ral-v1',JSON.stringify({colors:state.colors,saved}));}catch{toast('Не удалось сохранить в браузере. Скачайте спецификацию.');}}
function validColor(c){return c===null||(c&&paletteByCode[c.code]&&Number.isFinite(c.light)&&c.light>=0&&c.light<=70);}
try{const old=JSON.parse(localStorage.getItem('facade-ral-v1')||'null');if(old?.colors?.length===4&&old.colors.every(validColor))state.colors=old.colors;if(Array.isArray(old?.saved))saved=old.saved.filter(v=>v.colors?.length===4&&v.colors.every(validColor)&&typeof v.name==='string').slice(0,30);}catch{}
function schedule(){cancelAnimationFrame(frame);frame=requestAnimationFrame(render);}
function update(){
 $('zones').replaceChildren(...zones.map((name,i)=>{const b=document.createElement('button');b.className='zone'+(state.zone===i?' active':'');b.setAttribute('aria-pressed',state.zone===i);b.innerHTML='<i></i><span></span>';b.querySelector('i').style.background=cssColor(state.colors[i],i);b.querySelector('span').textContent=name;b.onclick=()=>{state.zone=i;update();};return b;}));
 const c=state.colors[state.zone];$('selected').innerHTML='<div class="large-chip"></div><div><b></b><p></p></div>';$('selected').querySelector('.large-chip').style.background=cssColor(c,state.zone);$('selected').querySelector('b').textContent=c?'RAL '+c.code:'Оригинал';$('selected').querySelector('p').textContent=c?paletteByCode[c.code].name:zones[state.zone];
 $('lighten').value=c?.light||0;$('lighten').disabled=!c;$('lighten-value').textContent=(c?.light||0)+'%';
 $('summary').replaceChildren(...zones.map((name,i)=>{const item=document.createElement('div');item.className='summary-item';item.innerHTML='<i class="chip"></i><div><span></span><b></b></div>';item.querySelector('i').style.background=cssColor(state.colors[i],i);item.querySelector('span').textContent=name;item.querySelector('b').textContent=label(state.colors[i]);return item;}));
 $('photo-tag').textContent=state.mask?'КАРТА УЧАСТКОВ':state.compare?'СЛЕВА — ИСХОДНОЕ · СПРАВА — ВАРИАНТ':state.colors.some(Boolean)?'ВАШ ВАРИАНТ':'ИСХОДНЫЙ ФАСАД';
 $('views').querySelectorAll('button').forEach(b=>b.classList.toggle('active',Number(b.dataset.view)===state.view));
 renderSwatches();schedule();persist();if(typeof refreshEditor==='function')refreshEditor();
}
function renderSwatches(){const q=$('search').value.trim().toLowerCase().replace(/^ral\s*/,'');const family=$('family').value;const list=RAL.filter(c=>(family==='all'||c.family===family)&&(c.code.includes(q)||c.name.toLowerCase().includes(q)));$('count').textContent=list.length+' цветов';$('swatches').replaceChildren(...list.map(c=>{const b=document.createElement('button');b.className='swatch'+(state.colors[state.zone]?.code===c.code?' active':'');b.title='RAL '+c.code+' · '+c.name;b.setAttribute('aria-label',b.title);b.setAttribute('aria-pressed',state.colors[state.zone]?.code===c.code);b.innerHTML='<i></i><span>'+c.code+'</span>';b.querySelector('i').style.background=c.hex;b.onclick=()=>{state.colors[state.zone]={code:c.code,light:0};update();};return b;}));if(!list.length){const e=document.createElement('div');e.className='empty';e.textContent='Нет такого оттенка в подборке. Попробуйте другой код или название.';$('swatches').append(e);}}
function transformPixels(original,mask,colors,reference,showMask=false){const output=new Uint8ClampedArray(original);const targets=colors.map(colorRGB);const zoneColors=[[229,116,83],[56,164,151],[205,167,78],[113,95,167]];for(let p=0,i=0;p<mask.length;p++,i+=4){const z=mask[p]-1;if(z<0||z>3)continue;if(showMask){for(let c=0;c<3;c++)output[i+c]=original[i+c]*.4+zoneColors[z][c]*.6;continue;}if(!targets[z])continue;const lum=.2126*original[i]+.7152*original[i+1]+.0722*original[i+2];const shade=Math.max(.22,Math.min(1.28,lum/reference[z]));for(let c=0;c<3;c++)output[i+c]=targets[z][c]*shade;}return output;}
function render(){if(!state.ready)return;const d=data[state.view],canvas=$('canvas');if(canvas.width!==d.width){canvas.width=d.width;canvas.height=d.height;}const out=transformPixels(d.original,d.mask,state.colors,d.reference,state.mask);if(state.compare&&!state.mask){const edge=Math.round(d.width*state.split/100);for(let y=0;y<d.height;y++){const start=y*d.width*4;out.set(d.original.subarray(start,start+edge*4),start);}}ctx.putImageData(new ImageData(out,d.width,d.height),0,0);$('compare-line').style.display=state.compare&&!state.mask?'block':'none';$('compare-line').style.left=state.split+'%';}
function loadImage(url){return new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>resolve(im);im.onerror=()=>reject(new Error('Изображение недоступно'));im.src=url;});}
async function init(){try{const [meta,geometry]=await Promise.all([fetch('assets/views.json?v=2').then(r=>r.json()),fetch('assets/geometry.json?v=2').then(r=>r.json())]);await Promise.all(meta.map(async(m,i)=>{const [im,mi,oi]=await Promise.all([loadImage('assets/view-'+i+'.jpg'),loadImage('assets/mask-'+i+'.png?v=2'),loadImage('assets/occlusion-'+i+'.png?v=2')]);const c=document.createElement('canvas');c.width=m.width;c.height=m.height;const x=c.getContext('2d',{willReadFrequently:true});x.drawImage(im,0,0);const original=x.getImageData(0,0,m.width,m.height).data;x.clearRect(0,0,m.width,m.height);x.drawImage(mi,0,0);const raw=x.getImageData(0,0,m.width,m.height).data,mask=new Uint8Array(m.width*m.height);for(let p=0;p<mask.length;p++)mask[p]=raw[p*4];x.clearRect(0,0,m.width,m.height);x.drawImage(oi,0,0);const op=x.getImageData(0,0,m.width,m.height).data,occlusion=new Uint8Array(mask.length);for(let p=0;p<mask.length;p++)occlusion[p]=op[p*4]>127?1:0;data[i]={...m,original,mask,baseMask:mask.slice(),occlusion,shapes:clone(geometry.views[i].shapes),baseShapes:clone(geometry.views[i].shapes),strokes:[],undo:[]};}));state.ready=true;$('loading').hidden=true;if(typeof setupEditor==='function')setupEditor();update();}catch(e){$('loading').textContent='Не удалось загрузить фото. Обновите страницу.';toast(e.message);}}
function presetButton(p){const b=document.createElement('button');b.className='preset';const strips=document.createElement('div');strips.className='preset-colors';p.codes.forEach(code=>{const i=document.createElement('i');i.style.background=paletteByCode[code].hex;strips.append(i);});const name=document.createElement('b');name.textContent=p.name;const code=document.createElement('small');code.textContent=p.codes.map(c=>'RAL '+c).join(' / ');b.append(strips,name,code);b.onclick=()=>{state.colors=p.codes.map(code=>({code,light:0}));update();toast('Применено: '+p.name);};return b;}
function showPresets(ps){$('presets').replaceChildren(...ps.map(presetButton));}
function hsl(hex){let [r,g,b]=rgb(hex).map(v=>v/255),max=Math.max(r,g,b),min=Math.min(r,g,b),delta=max-min,h=0,l=(max+min)/2,s=0;if(delta){s=delta/(1-Math.abs(2*l-1));h=max===r?((g-b)/delta)%6:max===g?(b-r)/delta+2:(r-g)/delta+4;h=((h*60)+360)%360;}return [h,s,l];}
function hueDistance(a,b){const d=Math.abs(a-b);return Math.min(d,360-d);}
function nearest(h,s,l,exclude=[]){return RAL.filter(c=>!exclude.includes(c.code)).sort((a,b)=>{const score=c=>{const x=hsl(c.hex);return (Math.min(s,x[1])>.08?hueDistance(h,x[0])/180:0)*.65+Math.abs(s-x[1])*.8+Math.abs(l-x[2])*2;};return score(a)-score(b);})[0].code;}
function generateHarmonies(code,mode){const anchor=paletteByCode[code];const [h,s,l]=hsl(anchor.hex);return [0,1,2,3].map((v)=>{const shift=mode==='contrast'?155+v*10:mode==='analog'?-25+v*18:0;const complement=nearest((h+shift+360)%360,Math.min(s,.35),.42+v*.035,[code]);let codes=['9010',code,nearest(h,.08,.67),nearest(h,.12,.22)];if(mode==='analog')codes=['9002',code,complement,nearest(h,.15,.23)];if(mode==='contrast')codes=['9001',code,complement,'7016'];if(mode==='tonal')codes=[nearest(h,.06,.9-v*.025),code,nearest(h,Math.min(s,.23),.6+v*.04,[code]),nearest(h,.12,.2+v*.03)];return{name:['Светлый баланс','Мягкие оттенки','Глубина цвета','Архитектурный ритм'][v],codes};});}
function renderSaved(){$('saved').replaceChildren();if(!saved.length){const p=document.createElement('p');p.className='fineprint';p.textContent='Сохраните понравившееся сочетание — оно останется в этом браузере.';$('saved').append(p);return;}saved.forEach((v,i)=>{const card=document.createElement('div');card.className='saved-card';const colors=document.createElement('div');colors.className='preset-colors';v.colors.forEach((c,k)=>{const s=document.createElement('i');s.style.background=cssColor(c,k);colors.append(s);});const title=document.createElement('b');title.textContent=v.name;const actions=document.createElement('div');actions.className='saved-actions';const apply=document.createElement('button');apply.textContent='Применить ↗';apply.onclick=()=>{state.colors=clone(v.colors);update();};const del=document.createElement('button');del.className='delete';del.textContent='Удалить';del.onclick=()=>{saved.splice(i,1);persist();renderSaved();};actions.append(apply,del);card.append(colors,title,actions);$('saved').append(card);});}
function download(blob,name){const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),10000);}
function specification(){return {project:'Фасад · RAL Studio',date:new Date().toISOString(),view:state.view===0?'Фронтальный':'Перспектива',note:'Приближённые экранные цвета. Осветление создаёт производный оттенок. Маски фото могут требовать уточнения.',zones:zones.map((name,i)=>({zone:name,ral:state.colors[i]?.code||null,lightening_percent:state.colors[i]?.light||0,screen_rgb:colorRGB(state.colors[i]),original:!state.colors[i]}))};}
$('views').onclick=e=>{const b=e.target.closest('[data-view]');if(b){state.view=Number(b.dataset.view);update();}};
$('reset').onclick=()=>{state.colors=[null,null,null,null];update();toast('Исходные цвета восстановлены');};
$('original-zone').onclick=()=>{state.colors[state.zone]=null;update();};
$('search').oninput=renderSwatches;$('family').onchange=renderSwatches;
$('lighten').oninput=e=>{if(state.colors[state.zone]){state.colors[state.zone].light=Number(e.target.value);update();}};
$('compare').onchange=e=>{state.compare=e.target.checked;$('split').disabled=!state.compare;update();};$('split').oninput=e=>{state.split=Number(e.target.value);schedule();};
$('fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await $('photo').requestFullscreen();}catch{toast('Полноэкранный режим недоступен в этом браузере');}};
$('save').onclick=()=>{if(saved.length>=30){toast('Сохранено 30 вариантов. Удалите один, чтобы добавить новый.');return;}saved.unshift({name:'Вариант '+new Date().toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit'}),colors:clone(state.colors)});persist();renderSaved();toast('Вариант сохранён в этом браузере');};
$('palette-export').onclick=()=>download(new Blob([JSON.stringify(specification(),null,2)],{type:'application/json'}),'facade-ral-specification.json');
$('export').onclick=()=>{if(!state.ready)return toast('Подождите загрузки фотографий');const d=data[state.view],c=document.createElement('canvas');c.width=d.width;c.height=d.height;c.getContext('2d').putImageData(new ImageData(transformPixels(d.original,d.mask,state.colors,d.reference),d.width,d.height),0,0);c.toBlob(b=>{if(b){download(b,'facade-ral-view-'+(state.view+1)+'.png');toast('Скачивается фото без интерфейса и разделителя');}},'image/png');};
$('generate').onclick=()=>{const code=state.colors[state.zone]?.code||'5001';showPresets(generateHarmonies(code,$('harmony-mode').value));toast('Сочетания с RAL '+code+' · примените понравившуюся карточку');};
function canvasPoint(e){const rect=$('canvas').getBoundingClientRect(),d=data[state.view];return{x:(e.clientX-rect.left)*d.width/rect.width,y:(e.clientY-rect.top)*d.height/rect.height};}
function dab(point){const d=data[state.view],z=Number($('brush').value),radius=Number($('brush-size').value)*d.width/$('canvas').getBoundingClientRect().width/2;for(let y=Math.max(0,Math.floor(point.y-radius));y<=Math.min(d.height-1,Math.ceil(point.y+radius));y++)for(let x=Math.max(0,Math.floor(point.x-radius));x<=Math.min(d.width-1,Math.ceil(point.x+radius));x++){if((x-point.x)**2+(y-point.y)**2>radius**2)continue;const p=y*d.width+x;if(!currentStroke.has(p))currentStroke.set(p,d.mask[p]);d.mask[p]=z;}schedule();}
$('canvas').onpointerdown=e=>{if(!state.ready||$('brush').value==='off')return;e.preventDefault();painting=true;currentStroke=new Map();lastPoint=canvasPoint(e);$('canvas').setPointerCapture(e.pointerId);dab(lastPoint);};
$('canvas').onpointermove=e=>{if($('brush').value==='off')return;const r=$('photo').getBoundingClientRect(),sz=Number($('brush-size').value),cursor=$('brush-cursor');cursor.style.cssText=`display:block;width:${sz}px;height:${sz}px;left:${e.clientX-r.left-sz/2}px;top:${e.clientY-r.top-sz/2}px`;if(!painting)return;const p=canvasPoint(e),steps=Math.ceil(Math.hypot(p.x-lastPoint.x,p.y-lastPoint.y)/3);for(let j=1;j<=steps;j++)dab({x:lastPoint.x+(p.x-lastPoint.x)*j/steps,y:lastPoint.y+(p.y-lastPoint.y)*j/steps});lastPoint=p;};
function finishStroke(){if(painting){painting=false;const u=data[state.view].undo;u.push(currentStroke);if(u.length>25)u.shift();currentStroke=null;}}
$('canvas').onpointerup=finishStroke;$('canvas').onpointercancel=finishStroke;$('canvas').onpointerleave=()=>$('brush-cursor').style.display='none';
$('brush').onchange=()=>{const active=$('brush').value!=='off';$('photo').style.touchAction=active?'none':'pan-y';$('canvas').style.cursor=active?'crosshair':'default';if(!active)$('brush-cursor').style.display='none';};
$('undo').onclick=()=>{if(!state.ready)return;const u=data[state.view].undo.pop();if(u){u.forEach((v,p)=>data[state.view].mask[p]=v);schedule();}else toast('Нет мазков для отмены');};
$('mask-reset').onclick=()=>{if(!state.ready)return;const d=data[state.view];d.undo.push(new Map(Array.from(d.mask.entries()).filter(([i,v])=>v!==d.baseMask[i])));d.mask=d.baseMask.slice();schedule();toast('Исходная маска восстановлена');};
$('show-mask').onchange=e=>{state.mask=e.target.checked;update();};
showPresets(PRESETS);renderSaved();update();init();
